INSERT INTO products (organization_id, sku, slug, category, name, description, price, unit, price_note, image_url, contents, occasions, caution, sort_order, is_active)
VALUES ((SELECT id FROM organizations WHERE slug = 'occasionsbox'), 'box-love-you', 'love-you', 'box', 'Love You', 'The one to send when the words matter more than the occasion. A camel leather wristlet and a script keychain to carry, a blush notebook and a gold pen to write in, and a soy candle for the evening it gets opened.', 150.00, 'each', NULL, '/assets/img/OB0_7441-750w.jpg', '["Leather Wristlet | Camel color","Twin Sparrow | “Love You” Script Keychain","Ramona & Ruth | Soft Blush Slim Notebook","Vinoos | 100% Vegan | The wine gummies are suitable for vegetarians and vegans and without artificial colors. They are free of alcohol, gluten, fat, nuts, gelatine and lactose. 13 units","P.F. Candle Co. | Soy Candle | 7.2 oz | Sunbloom scent","OB | Mini signature matches - white tip","OB | Gold ballpoint pen","Occasions Box Keepsake box | measures 11” x 8.66” x 4.33”","A Complimentary Handwritten card of your choice"]'::jsonb, ARRAY['celebration']::text[], NULL, 10, true)
