INSERT INTO products (organization_id, sku, slug, category, name, description, price, unit, price_note, image_url, contents, occasions, caution, sort_order, is_active)
VALUES ((SELECT id FROM organizations WHERE slug = 'occasionsbox'), 'box-spa-weekend', 'spa-weekend', 'box', 'Spa Weekend', 'Two days off, boxed. A hand-loomed Turkish towel and eucalyptus mint body wash for the bath, a gold tin candle to light beside it, and lemon curd biscuits for afterwards.', 120.00, 'each', NULL, '/assets/img/OB0_7721-750w.jpg', '["Towel | Hand-Loomed Hand or Face Turkish Towel | Lime and White color","Long Wknd | Body wash soap | Eucalyptus Mint","Candlefish | No. 40 Gold Tin Soy Candle 7.5 oz | 40-50 Hours Burn Time | Rose, Lavender, Leather notes.","OB Mini Matches | Green tip matches","Lady Joseph | Delicate Lemon Curd Biscuits | Hand crafted in Spain using only natural ingredients | 3.5oz","Occasions Box Keepsake box | measures 11” x 8.66” x 4.33”","A Complimentary Handwritten card of your choice"]'::jsonb, ARRAY['selfcare']::text[], 'Contains eucalyptus mint body wash and lemon curd biscuits.', 30, true)
