  AND lower(i.brand) = lower('Occasions Box') AND lower(i.name) = lower('Keepsake box')
ON CONFLICT (product_id, inventory_item_id) DO UPDATE SET sort_order = EXCLUDED.sort_order;
INSERT INTO product_components (organization_id, product_id, inventory_item_id, quantity, sort_order)
SELECT (SELECT id FROM organizations WHERE slug = 'occasionsbox'), p.id, i.id, 1, 8
FROM products p JOIN inventory_items i ON i.organization_id = p.organization_id
WHERE p.organization_id = (SELECT id FROM organizations WHERE slug = 'occasionsbox') AND p.sku = 'box-afternoon-tea'
  AND lower(i.brand) = lower('Occasions Box') AND lower(i.name) = lower('Handwritten card')
ON CONFLICT (product_id, inventory_item_id) DO UPDATE SET sort_order = EXCLUDED.sort_order;

